<?php require_once __DIR__.'/config/auth.php';$admin=require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('users_list.php');verify_csrf();$id=(int)($_POST['id']??0);if($id===(int)$admin['id']){flash('error','You cannot delete your own account.');redirect('users_list.php');}$s=db()->prepare('SELECT role,status FROM users WHERE id=?');$s->execute([$id]);$target=$s->fetch();if(!$target){flash('error','User not found.');redirect('users_list.php');}if($target['role']==='admin'&&$target['status']==='active'&&(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'")->fetchColumn()<=1){flash('error','The last active administrator cannot be deleted.');redirect('users_list.php');}$s=db()->prepare('DELETE FROM users WHERE id=?');$s->execute([$id]);flash('success','User deleted.');redirect('users_list.php');
